#include <bits/stdc++.h>
using namespace std;

using lli = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lli n, k, a, b;
    cin >> n >> k >> a >> b;

    const lli total = n * k;
    lli minimum = LLONG_MAX;
    lli maximum = 0;

    auto update = [&](lli distance) {
        distance = abs(distance);
        if (distance == 0) return;

        lli count = total / std::gcd(distance, total);
        minimum = min(minimum, count);
        maximum = max(maximum, count);
    };

    for (lli i = 1; i <= n; ++i) {
        update(i * k + a + b);
        update(i * k + a - b);
        update(i * k - a + b);
        update(i * k - a - b);
    }

    cout << minimum << ' ' << maximum << '\n';
    return 0;
}

